score = {"a": ["b"], "b": ["c"], "c": ["b"]}
chalk, loop = set(), []
def rehearse(n, trail):
    chalk.add(n)
    for m in score[n]:
        if m in trail:
            loop.extend(trail[trail.index(m):] + [m]); return True
        if m not in chalk and rehearse(m, trail + [m]): return True
    return False
rehearse("a", ["a"])
print("Rite result — loop circled:", " -> ".join(loop))
assert loop == ["b", "c", "b"]

