import collections
scrolls = [collections.deque([f"doc-{i}-{j}" for j in range(6)]) for i in range(2)]
scrolls[0].clear()  # worker 0 finishes early
honor_log = []
while any(scrolls):
    for w, s in enumerate(scrolls):
        if s: s.popleft()
        else:
            donor = max(range(2), key=lambda v: len(scrolls[v]))
            if scrolls[donor]:
                scrolls[donor].pop(); honor_log.append((donor, w))
print("Honorable transfers:", len(honor_log))
assert len(honor_log) > 0

BRIM = 4
reservoir, spilled, gated = [], 0, 0
for drop in range(12):
    if len(reservoir) < BRIM: reservoir.append(drop)
    else: spilled += 1; gated += 1
    if drop % 3 == 0 and reservoir: reservoir.pop(0)
print(f"held={len(reservoir)} spilled={spilled} gate-closures={gated}")
assert len(reservoir) <= BRIM

